-- PostgreSQL schema: content is normalized and source provenance is retained per record.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE publication_status AS ENUM ('DRAFT', 'PUBLISHED', 'NEEDS_REVIEW', 'ARCHIVED');
CREATE TYPE source_kind AS ENUM ('OFFICIAL_WEBSITE', 'OFFICIAL_DOCUMENTATION', 'CBN', 'NIBSS', 'GOVERNMENT', 'COMPANY_FILING', 'REGULATORY_DOCUMENT', 'REPUTABLE_PUBLICATION');
CREATE TYPE relationship_kind AS ENUM ('PROVIDES', 'OPERATES', 'CONNECTS_TO', 'REGULATED_BY', 'PARTICIPATES_IN', 'USES', 'PROCESSES_FOR', 'COMPETES_WITH');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, role text NOT NULL DEFAULT 'EDITOR', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, url text NOT NULL UNIQUE, source_type source_kind NOT NULL, published_at timestamptz, last_verified_at timestamptz NOT NULL DEFAULT now(), verified_by uuid REFERENCES users(id));
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, description text);
CREATE TABLE entities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, entity_type text NOT NULL, description text NOT NULL, infrastructure_role text, website_url text, headquarters text, founded_year integer, status publication_status NOT NULL DEFAULT 'DRAFT', source_id uuid REFERENCES sources(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE entity_categories (entity_id uuid REFERENCES entities(id) ON DELETE CASCADE, category_id uuid REFERENCES categories(id) ON DELETE CASCADE, PRIMARY KEY(entity_id, category_id));
CREATE TABLE entity_relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_entity_id uuid NOT NULL REFERENCES entities(id) ON DELETE CASCADE, to_entity_id uuid NOT NULL REFERENCES entities(id) ON DELETE CASCADE, relationship_type relationship_kind NOT NULL, explanation text, source_id uuid REFERENCES sources(id), CHECK(from_entity_id <> to_entity_id));
CREATE INDEX entity_relationships_from_idx ON entity_relationships(from_entity_id); CREATE INDEX entity_relationships_to_idx ON entity_relationships(to_entity_id);
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid REFERENCES entities(id) ON DELETE CASCADE, name text NOT NULL, description text, source_id uuid REFERENCES sources(id));
CREATE TABLE api_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid REFERENCES entities(id) ON DELETE CASCADE, slug text UNIQUE NOT NULL, name text NOT NULL, category text NOT NULL, auth_method text, sandbox_available boolean, webhook_support boolean, documentation_url text, use_case text, status publication_status NOT NULL DEFAULT 'DRAFT', source_id uuid REFERENCES sources(id));
CREATE TABLE regulations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, title text NOT NULL, summary text NOT NULL, regulator_id uuid REFERENCES entities(id), official_url text, source_id uuid REFERENCES sources(id));
CREATE TABLE licenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid REFERENCES entities(id), regulator_id uuid REFERENCES entities(id), category text NOT NULL, summary text, source_id uuid REFERENCES sources(id));
CREATE TABLE infrastructure (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, description text NOT NULL, operator_id uuid REFERENCES entities(id), source_id uuid REFERENCES sources(id));
CREATE TABLE payment_rails (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, description text NOT NULL, source_id uuid REFERENCES sources(id));
CREATE TABLE transaction_flows (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, summary text NOT NULL, status publication_status NOT NULL DEFAULT 'DRAFT', source_id uuid REFERENCES sources(id));
CREATE TABLE transaction_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), flow_id uuid NOT NULL REFERENCES transaction_flows(id) ON DELETE CASCADE, position integer NOT NULL, title text NOT NULL, description text NOT NULL, technical_note text, entity_id uuid REFERENCES entities(id), UNIQUE(flow_id, position));
CREATE TABLE glossary_terms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, term text NOT NULL, definition text NOT NULL, source_id uuid REFERENCES sources(id));
CREATE TABLE contributions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), type text NOT NULL, payload jsonb NOT NULL, status publication_status NOT NULL DEFAULT 'NEEDS_REVIEW', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
